//! Swift bindings for the menu bar app, generated by UniFFI.
//!
//! The types mirror [`wgd::menu_bar`] one to one, so the `wgd` library stays
//! free of UniFFI. All logic lives there; this crate only converts.

use wgd::menu_bar;

uniffi::setup_scaffolding!();

#[derive(uniffi::Enum)]
pub enum Overall {
    Active,
    PulledBack,
    Inactive,
    Disconnected,
    NoConnections,
    Unavailable,
}

#[derive(uniffi::Record)]
pub struct Snapshot {
    pub overall: Overall,
    pub connections: Vec<ConnectionLine>,
    pub error: Option<String>,
}

#[derive(uniffi::Record)]
pub struct ConnectionLine {
    pub title: String,
    pub interface: String,
    pub global: bool,
    pub connected: bool,
    pub state: Overall,
    pub detail: String,
}

/// Blocks on the privileged daemon (bounded by a request timeout); call it
/// off the main thread.
#[uniffi::export]
pub fn snapshot() -> Snapshot {
    menu_bar::snapshot().into()
}

/// Same label `wgd --version` prints, from the build this app was linked in.
#[uniffi::export]
pub fn build_label() -> String {
    wgd::BUILD_LABEL.to_string()
}

/// The Darwin notification name daemon and helper post on status changes
/// (see `wgd::status_notify`).
#[uniffi::export]
pub fn status_notification_name() -> String {
    wgd::status_notify::NAME.to_string_lossy().into_owned()
}

impl From<menu_bar::Overall> for Overall {
    fn from(state: menu_bar::Overall) -> Self {
        match state {
            menu_bar::Overall::Active => Self::Active,
            menu_bar::Overall::PulledBack => Self::PulledBack,
            menu_bar::Overall::Inactive => Self::Inactive,
            menu_bar::Overall::Disconnected => Self::Disconnected,
            menu_bar::Overall::NoConnections => Self::NoConnections,
            menu_bar::Overall::Unavailable => Self::Unavailable,
        }
    }
}

impl From<menu_bar::Snapshot> for Snapshot {
    fn from(snap: menu_bar::Snapshot) -> Self {
        Self {
            overall: snap.overall.into(),
            connections: snap.connections.into_iter().map(Into::into).collect(),
            error: snap.error,
        }
    }
}

impl From<menu_bar::ConnectionLine> for ConnectionLine {
    fn from(line: menu_bar::ConnectionLine) -> Self {
        Self {
            title: line.title,
            interface: line.interface,
            global: line.global,
            connected: line.connected,
            state: line.state.into(),
            detail: line.detail,
        }
    }
}
